-- submit_request (v4): fallback to auth.users.email when public.user_profiles.email is null so the requester confirmation email always has a recipient.
CREATE OR REPLACE FUNCTION app_procurement.submit_request(p_notes text, p_line_items jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = app_procurement, public AS $fn$ DECLARE v_id uuid; v_name text; v_email text; li jsonb; BEGIN IF NOT public.check_user_permission(auth.uid(), 'apps/procurement/requests/create') THEN RAISE EXCEPTION 'Not permitted to create requests'; END IF; SELECT COALESCE(up.display_name, au.email), COALESCE(up.email, au.email) INTO v_name, v_email FROM auth.users au LEFT JOIN public.user_profiles up ON up.id = au.id WHERE au.id = auth.uid(); INSERT INTO app_procurement.purchase_requests (requester_id, requester_name, requester_email, requester_type, submission_source, status, notes, submitted_at) VALUES (auth.uid(), v_name, v_email, 'portal_user', 'in_portal', 'pending', p_notes, now()) RETURNING id INTO v_id; FOR li IN SELECT * FROM jsonb_array_elements(coalesce(p_line_items, '[]'::jsonb)) LOOP INSERT INTO app_procurement.line_items (request_id, ship_to_name, location_id, custom_location, department_id, custom_department, item_url, item_description, memo, quantity, substitution_ok, date_needed, status) VALUES (v_id, li->>'ship_to_name', nullif(li->>'location_id','')::uuid, li->>'custom_location', nullif(li->>'department_id','')::uuid, li->>'custom_department', li->>'item_url', li->>'item_description', li->>'memo', coalesce((li->>'quantity')::int,1), coalesce((li->>'substitution_ok')::boolean,false), nullif(li->>'date_needed','')::date, 'pending'); END LOOP; RETURN v_id; END; $fn$;

-- Backfill requests created with a null requester_email when auth.users has an email.
UPDATE app_procurement.purchase_requests pr SET requester_email = au.email FROM auth.users au WHERE pr.requester_id = au.id AND pr.requester_email IS NULL AND au.email IS NOT NULL;
